package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20) // PIC X(20) len=20 = SPACES
var WsACount int64 = 0 // PIC 99 len=2 = 0
var WsTotalA int64 = 0 // PIC 999 len=3 = 0
var WsCount int64 = 0 // PIC 999 len=3 = 0

var curRec PartRec
var inRecords []PartRec
var inIdx int

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	var lines []string
	if len(data) == 0 {
		lines = nil
	} else {
		raw := strings.Split(string(data), "\n")
		if strings.HasSuffix(string(data), "\n") {
			raw = raw[:len(raw)-1]
		}
		lines = raw
		for i, l := range lines {
			if len(l) > 0 && l[len(l)-1] == '\r' {
				lines[i] = l[:len(l)-1]
			}
		}
	}
	inRecords = nil
	inIdx = 0
	for _, ln := range lines {
		s := ln
		if len(s) < 15 {
			s = s + strings.Repeat(" ", 15-len(s))
		} else if len(s) > 15 {
			s = s[:15]
		}
		lbPart := s[0:8]
		lbRegion := s[8:11]
		serStr := s[11:15]
		var ser int64
		t := strings.TrimSpace(serStr)
		if t == "" {
			ser = 0
		} else {
			v, e := strconv.ParseInt(t, 10, 64)
			if e != nil {
				ser = 0
			} else {
				ser = v
			}
		}
		// keep low-order 4 digits
		ser = ((ser % 10000) + 10000) % 10000
		inRecords = append(inRecords, PartRec{
			LbPart:   lbPart,
			LbRegion: lbRegion,
			LbSerial: ser,
		})
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if inIdx >= len(inRecords) {
		WsEofFlag = "Y"
	} else {
		curRec = inRecords[inIdx]
		inIdx++
	}
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	var cnt int64 = 0
	for i := 0; i < len(curRec.LbPart); i++ {
		if curRec.LbPart[i] == 'A' {
			cnt++
		}
	}
	WsACount = cnt % 100

	target := make([]byte, 20)
	for i := range target {
		target[i] = ' '
	}
	pos := 0
	copyInto := func(src string) {
		for i := 0; i < len(src) && pos < 20; i++ {
			target[pos] = src[i]
			pos++
		}
	}
	s1 := curRec.LbRegion
	if idx := strings.IndexByte(s1, ' '); idx >= 0 {
		s1 = s1[:idx]
	}
	copyInto(s1)
	copyInto("-")
	s3 := curRec.LbPart
	if idx := strings.IndexByte(s3, ' '); idx >= 0 {
		s3 = s3[:idx]
	}
	copyInto(s3)
	copyInto("-")
	serMod := ((curRec.LbSerial % 10000) + 10000) % 10000
	s5 := fmt.Sprintf("%04d", serMod)
	copyInto(s5)
	WsLabel = string(target)
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000

	ac := ((WsACount % 100) + 100) % 100
	fmt.Fprintf(os.Stdout, "%s A=%02d\n", WsLabel, ac)
	ReadPara()
}

func SummaryPara() {
	c := ((WsCount % 1000) + 1000) % 1000
	t := ((WsTotalA % 1000) + 1000) % 1000
	fmt.Fprintf(os.Stdout, "LABELS: %03d A-TOTAL: %03d\n", c, t)
}

func main() {
	MainPara()
}
